import type { Recommendation } from "./types";
import type { EvidenceEvaluation } from "./evaluation";

/**
 * Formats secondary claim research recommendations into a clean exportable text document
 * suitable for review with a VSO or medical representative.
 */
export function formatClaimSummary(
  recommendations: Recommendation[],
  evaluations: EvidenceEvaluation[],
): string {
  const lines: Array<string> = [
    "SECONDARY CLAIM RESEARCH & EVIDENCE CHECKLIST",
    "Generated by Secondary Condition Finder (38 CFR § 3.310 Research Tool)",
    "=".repeat(60),
    "",
  ];

  recommendations.forEach((rec, index) => {
    const evaluation = evaluations.find((entry) => entry.conditionId === rec.conditionId);
    lines.push(`${index + 1}. Recommended Theory: ${rec.condition} (${rec.bodySystem})`);
    lines.push(`   Etiological Consensus: ${rec.etiologicalConsensus}`);
    lines.push(`   Contributing Primaries: ${rec.contributingPrimaries.map((primary) => primary.name).join(", ")}`);

    if (evaluation) {
      lines.push(`   Satisfied Gaps: ${evaluation.satisfiedGaps.join("; ") || "None yet"}`);
      lines.push(`   Remaining Gaps: ${evaluation.remainingGaps.join("; ") || "None yet"}`);
    } else {
      lines.push(`   Evidence Gaps to Review: ${rec.evidenceGaps.join("; ") || "None listed"}`);
    }

    lines.push("   Key Sources:");
    rec.sourceReferences.forEach((reference) => {
      lines.push(`     - ${reference.citation}`);
      lines.push(`       Note: ${reference.note}`);
      lines.push(`       Verification: ${reference.verified ? "VERIFIED" : "UNVERIFIED — confirm before relying on this source"}`);
      lines.push(`       Scope: ${reference.verificationScope ?? "legal-framework"}`);
      if (reference.sourceUrl) lines.push(`       Source URL: ${reference.sourceUrl}`);
      if (reference.sourceLocator) lines.push(`       Source locator: ${reference.sourceLocator}`);
      if (reference.sourceCheckedOn) lines.push(`       Source checked on: ${reference.sourceCheckedOn}`);
    });
    lines.push("-".repeat(40));
  });

  lines.push("");
  lines.push("DISCLAIMER: This document is for educational and research preparation purposes only.");
  lines.push("It does not constitute medical diagnosis, legal advice, or a guaranteed VA claim outcome.");
  lines.push("Any source marked UNVERIFIED is a research starting point and must be independently confirmed before reliance.");

  return lines.join("\n");
}
